using System.Text.Json;
using System.Text.Encodings.Web;
using VisualQa.Core;
namespace VisualQa.Reporting;
public sealed class JsonReportWriter { public void Write(QaReport report,string path)=>File.WriteAllText(path,JsonSerializer.Serialize(report,new JsonSerializerOptions{WriteIndented=true})); }
public sealed class HtmlReportWriter { public void Write(QaReport report,string path) { var rows=string.Join("",report.Findings.Select(x=>$"<tr><td>{E(x.Rule)}</td><td>{E(x.ElementId)}</td><td class='{x.Status}'>{x.Status}</td><td>{E(x.Message)}</td></tr>"));var images=string.Join("",report.Artifacts.Where(x=>x.Key.EndsWith(".png")).Select(x=>$"<figure><figcaption>{x.Key}</figcaption><img src='{E(x.Value)}'></figure>"));File.WriteAllText(path,$"<!doctype html><meta charset='utf-8'><style>body{{font:14px system-ui;margin:2rem}}table{{border-collapse:collapse;width:100%}}td,th{{border:1px solid #ddd;padding:.4rem}}.Fail,.Error{{color:#b00020}}.Warning{{color:#996600}}.Pass{{color:#067d28}}img{{max-width:420px;border:1px solid #ccc}}figure{{display:inline-block;vertical-align:top}}</style><h1>Visual QA: {E(report.Component)} / {E(report.Platform)}</h1><p>Overall: <b class='{report.Status}'>{report.Status}</b>; similarity: {report.Similarity:P2}</p><div>{images}</div><table><tr><th>Rule</th><th>Element</th><th>Status</th><th>Evidence</th></tr>{rows}</table>");} static string E(string? s)=>HtmlEncoder.Default.Encode(s??""); }
